export const footerCopyrightText = (t: TranslateFn): BlockItem => ({
  title: t('block.footerCopyrightText.title'),
  description: t('block.footerCopyrightText.description'),
  searchTerms: ['footer', 'copyright'],
  icon: <IconPlaceholder
  lucide="CopyrightIcon"
  tabler="IconCopyright"
  hugeicons="CopyrightIcon"
  phosphor="Copyright"
  remixicon="RiCopyrightLine"
  className="h-4 w-4"
/>,
  command: ({ editor, range }) => {
    const currentYear = new Date().getFullYear();

    editor
      .chain()
      .focus()
      .deleteRange(range)
      .insertContent({
        type: 'paragraph',
        attrs: { textAlign: 'center', showIfKey: null },
        content: [
          {
            type: 'text',
            marks: [{ type: 'textStyle', attrs: { color: '#AAAAAA' } }],
            text: `Maily © ${currentYear}. All rights reserved.`,
          },
