export const inlineImage = (t: TranslateFn): BlockItem => ({
  title: t('block.inlineImage.title'),
  description: t('block.inlineImage.description'),
  searchTerms: ['image', 'inline'],
  icon: <IconPlaceholder
  lucide="ImageIcon"
  tabler="IconPhoto"
  hugeicons="Image01Icon"
  phosphor="ImageSquare"
  remixicon="RiImage2Line"
  className="h-4 w-4"
/>,
  command: ({ editor, range }) => {
    // @ts-ignore
    editor
      .chain()
      .focus()
      .deleteRange(range)
      // @ts-ignore
      .setInlineImage({
        src: 'https://raw.githubusercontent.com/brokeboiflex/maily.cn/main/assets/branding/maily-cn-avatar.png',
      })
      // @ts-ignore
      .command((props) => {
        const { tr, state, view: _view, editor: _editor } = props;
        const { from } = range;

        const node = state.doc.nodeAt(from);
        if (!node) {
          return false;
        }

        const selection = TextSelection.create(
          tr.doc,
          from,
          from + node.nodeSize
        );
        tr.setSelection(selection);
        return true;
      })
      .run();
  },
});

