          icon={<IconPlaceholder
  lucide="Space"
  tabler="IconSpace"
  hugeicons="HorizontalResizeIcon"
  phosphor="ArrowsOutLineHorizontal"
  remixicon="RiSpace"
/>}
          label={t('columnMenu.gap')}
          value={state.currentColumnsGap}
          options={[
            { value: '0', label: t('columnMenu.gap.none') },
            ...spacing.map((space) => ({
