                  ?.chain()
                  .updateAttributes('image', {
                    borderRadius: Number(value),
                  })
                  .run();
              }}
              tooltip={t('imageMenu.borderRadius')}
              className="capitalize"
            />

            <div className="flex gap-x-0.5">
              <ImageSize
                dimension="width"
                value={state?.width ?? ''}
                onValueChange={(value) => {
                  const width = Math.min(Number(value) || 0, IMAGE_MAX_WIDTH);
                  const currentHeight = Number(state.height) || 0;
                  const currentWidth = Number(state.width) || 0;
                  const hasValidAspectRatio =
                    state.aspectRatio &&
                    isFinite(state.aspectRatio) &&
                    state.aspectRatio > 0;
                  const currentAspectRatio = hasValidAspectRatio
                    ? state.aspectRatio
                    : currentHeight > 0
                      ? currentWidth / currentHeight
                      : 1;
                  const isHeightAuto = !state.height || state.height === 'auto';
                  const shouldUpdateHeight =
                    (lockAspectRatio || isHeightAuto) &&
                    value &&
                    (hasValidAspectRatio || currentHeight > 0);

                  editor
                    ?.chain()
                    .updateAttributes('image', {
                      width: String(width),
                      ...(shouldUpdateHeight
                        ? {
                            height: String(
                              getNewHeight(width, currentAspectRatio)
                            ),
                          }
                        : {}),
                    })
                    .run();
                }}
              />
              <ImageSize
                dimension="height"
                value={state?.height ?? ''}
                onValueChange={(value) => {
                  const height = Number(value) || 0;
                  const currentHeight = Number(state.height) || 0;
                  const currentWidth = Number(state.width) || 0;
                  const hasValidAspectRatio =
                    state.aspectRatio &&
                    isFinite(state.aspectRatio) &&
                    state.aspectRatio > 0;
                  const currentAspectRatio = hasValidAspectRatio
                    ? state.aspectRatio
                    : currentHeight > 0
                      ? currentWidth / currentHeight
                      : 1;
                  const isWidthAuto = !state.width || state.width === 'auto';
                  const shouldUpdateWidth =
                    (lockAspectRatio || isWidthAuto) &&
                    value &&
                    (hasValidAspectRatio || currentWidth > 0);

                  editor
                    ?.chain()
                    .updateAttributes('image', {
                      height: String(height),
                      ...(shouldUpdateWidth
                        ? {
                            width: String(
                              getNewWidth(height, currentAspectRatio)
                            ),
                          }
                        : {}),
                    })
                    .run();
                }}
              />

              <BubbleMenuButton
                isActive={() => lockAspectRatio}
                command={() => {
                  const width = Number(state.width) || 0;
                  const height = Number(state.height) || 0;
                  const aspectRatio = width / height;

                  editor
                    ?.chain()
                    .updateAttributes('image', {
                      lockAspectRatio: !lockAspectRatio,
                      aspectRatio,
                    })
                    .run();
                }}
                icon={lockAspectRatio ? <IconPlaceholder
  lucide="LockIcon"
  tabler="IconLock"
  hugeicons="LockIcon"
  phosphor="Lock"
  remixicon="RiLockLine"
/> : <IconPlaceholder
  lucide="LockOpenIcon"
  tabler="IconLockOpen"
  hugeicons="SquareUnlock01Icon"
  phosphor="LockOpen"
  remixicon="RiLockUnlockLine"
/>}
                tooltip={t('imageMenu.lockAspectRatio')}
              />
            </div>
          </>
        )}

        <Separator orientation="vertical" />
        <ShowPopover
          showIfKey={state.currentShowIfKey}
          onShowIfKeyValueChange={(value) => {
            editor
              ?.chain()
              .updateAttributes(state.isLogoActive ? 'logo' : 'image', {
                showIfKey: value,
              })
              .run();
          }}
          editor={editor}
        />
      </TooltipProvider>
    </BubbleMenu>
  );
}

