const EMPTY_SELECT_VALUE = '__maily-empty-value__';

type SelectProps = {
  label: string;
  options: {
    value: string;
    label: string;
  }[];

  value: string;
  onValueChange: (value: string) => void;

  tooltip?: string;
  className?: string;
  onCloseAutoFocus?: () => void;

  icon?: ReactNode;

  placeholder?: string;
};

function toPrimitiveValue(value: string) {
  return value === '' ? EMPTY_SELECT_VALUE : value;
}

function fromPrimitiveValue(value: string) {
  return value === EMPTY_SELECT_VALUE ? '' : value;
}

export function Select(props: SelectProps) {
  const {
    label,
    options,
    value,
    onValueChange,
    className,
    icon,
    placeholder,
    onCloseAutoFocus,
    tooltip,
  } = props;

  const selectId = `mly${useId()}`;

  return (
    <SelectControl
      selectId={selectId}
      label={label}
      options={options}
      value={value}
      onValueChange={onValueChange}
      className={className}
      icon={icon}
      placeholder={placeholder}
      onCloseAutoFocus={onCloseAutoFocus}
      tooltip={tooltip}
    />
  );
}

type SelectControlProps = SelectProps & {
  selectId: string;
};

function SelectControl({
  selectId,
  label,
  options,
  value,
  onValueChange,
  className,
  icon,
  placeholder,
  onCloseAutoFocus,
  tooltip,
}: SelectControlProps) {
  const [open, setOpen] = useState(false);
  const wasOpenRef = useRef(false);
  const selectedValue = toPrimitiveValue(value || '');
  const activeLabel =
    options.find((option) => option.value === (value || ''))?.label ||
    placeholder ||
    label;

  const handleOpenChange = (nextOpen: boolean) => {
    const wasOpen = wasOpenRef.current;
    wasOpenRef.current = nextOpen;
    setOpen(nextOpen);

    if (wasOpen && !nextOpen && onCloseAutoFocus) {
      window.requestAnimationFrame(onCloseAutoFocus);
    }
  };

  return (
    <div className="relative inline-flex">
      <label htmlFor={selectId} className="sr-only">
        {label}
      </label>

      <Popover open={open} onOpenChange={handleOpenChange}>
        {tooltip ? (
          <Tooltip>
            <TooltipTrigger asChild>
              <span className="inline-flex shrink-0">
                <PopoverTrigger asChild>
                  <Button
                    id={selectId}
                    type="button"
                    variant="ghost"
                    size="sm"
                    aria-label={label}
                    aria-expanded={open}
                    className={cn(
                      FLOATING_MENU_TRIGGER_CLASS,
                      'max-w-max',
                      className
                    )}
                  >
                    {icon && (
                      <span className="text-muted-foreground flex size-3 shrink-0 items-center justify-center [&_svg]:size-3">
                        {icon}
                      </span>
                    )}
                    <span className="truncate text-xs font-medium">
                      {activeLabel}
                    </span>
                    <IconPlaceholder
  lucide="ChevronDownIcon"
  tabler="IconChevronDown"
  hugeicons="ChevronDownIcon"
  phosphor="CaretDown"
  remixicon="RiArrowDownSLine"
  className="text-muted-foreground size-3 shrink-0"
/>
                  </Button>
                </PopoverTrigger>
              </span>
            </TooltipTrigger>
            <TooltipContent sideOffset={8}>{tooltip}</TooltipContent>
          </Tooltip>
        ) : (
          <PopoverTrigger asChild>
            <Button
              id={selectId}
              type="button"
              variant="ghost"
              size="sm"
              aria-label={label}
              aria-expanded={open}
              className={cn(
                FLOATING_MENU_TRIGGER_CLASS,
                'max-w-max',
                className
              )}
            >
              {icon && (
                <span className="text-muted-foreground flex size-3 shrink-0 items-center justify-center [&_svg]:size-3">
                  {icon}
                </span>
              )}
              <span className="truncate text-xs font-medium">
                {activeLabel}
              </span>
              <IconPlaceholder
  lucide="ChevronDownIcon"
  tabler="IconChevronDown"
  hugeicons="ChevronDownIcon"
  phosphor="CaretDown"
  remixicon="RiArrowDownSLine"
  className="text-muted-foreground size-3 shrink-0"
/>
            </Button>
          </PopoverTrigger>
        )}
        <PopoverContent
          {...BOTTOM_FLOATING_CONTENT_PROPS}
          align="start"
          sideOffset={8}
          className="max-h-80 min-w-36 gap-0 overflow-y-auto p-1"
        >
          <ToggleGroupCompat
            selectionMode="single"
            value={selectedValue}
            className="flex-col items-stretch gap-0.5"
          >
            {options.map((option) => {
              const optionValue = toPrimitiveValue(option.value);

              return (
                <ToggleGroupCompatItem
                  key={optionValue}
                  value={optionValue}
                  pressed={selectedValue === optionValue}
                  onClick={() => {
                    onValueChange(fromPrimitiveValue(optionValue));
                    handleOpenChange(false);
                  }}
                  aria-label={option.label}
                  className="h-7! justify-start px-2 text-sm"
                  type="button"
                >
                  {option.label}
                </ToggleGroupCompatItem>
              );
            })}
          </ToggleGroupCompat>
        </PopoverContent>
      </Popover>
    </div>
  );
}

import { forwardRef } from 'react';
import type {
  ButtonHTMLAttributes,
  ComponentType,
  HTMLAttributes,
  ReactNode,
  RefAttributes,
} from 'react';
import {
  ToggleGroup as ShadcnToggleGroup,
  ToggleGroupItem as ShadcnToggleGroupItem,
} from '@/components/ui/toggle-group';

type SelectionMode = 'single' | 'multiple';
type ToggleValue = string | string[];

type ToggleGroupCompatProps = Omit<
  HTMLAttributes<HTMLDivElement>,
  'onChange'
> & {
  selectionMode: SelectionMode;
  value: ToggleValue;
  variant?: 'default' | 'outline' | null;
  size?: 'default' | 'sm' | 'lg' | null;
  spacing?: number;
  orientation?: 'horizontal' | 'vertical';
  children: ReactNode;
};

type ToggleGroupCompatItemProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  value: string;
  pressed: boolean;
  variant?: 'default' | 'outline' | null;
  size?: 'default' | 'sm' | 'lg' | null;
};

// Radix uses `type` plus string/string[] values while Base UI uses `multiple`
// plus array values. shadcn exposes those backend-specific signatures. This
// adapter keeps the host's real ToggleGroup and ToggleGroupItem at runtime,
// while controlling each item through the common button state both backends
// expose. The Radix primitive owns `pressed`; Base UI consumes the supplied one.
const ToggleGroupRoot = ShadcnToggleGroup as ComponentType<
  Omit<ToggleGroupCompatProps, 'selectionMode'> & { type: SelectionMode }
>;
const ToggleGroupItem = ShadcnToggleGroupItem as ComponentType<
  ToggleGroupCompatItemProps & RefAttributes<HTMLButtonElement>
>;

export function ToggleGroupCompat({
  selectionMode,
  ...props
}: ToggleGroupCompatProps) {
  return <ToggleGroupRoot type={selectionMode} {...props} />;
}

export const ToggleGroupCompatItem = forwardRef<
  HTMLButtonElement,
  ToggleGroupCompatItemProps
>((props, ref) => <ToggleGroupItem ref={ref} {...props} />);
ToggleGroupCompatItem.displayName = 'ToggleGroupCompatItem';

import { BubbleMenu } from '@tiptap/react';
import { sticky } from 'tippy.js';
import { TextBubbleContent } from '../text-menu/text-bubble-content';
import { type EditorBubbleMenuProps } from '../text-menu/text-bubble-menu';
import { TooltipProvider } from '@/components/ui/tooltip';
import { FLOATING_BUBBLE_MENU_CLASS } from '../ui/floating-menu';

export function VariableBubbleMenu(props: EditorBubbleMenuProps) {
  const { editor, appendTo } = props;
  if (!editor) {
    return null;
  }

  const bubbleMenuProps: EditorBubbleMenuProps = {
    ...props,
    pluginKey: 'variable-menu',
    shouldShow: ({ editor }) => {
      return editor.isActive('variable') && !editor.storage.variable?.popover;
    },
    tippyOptions: {
      popperOptions: {
        modifiers: [{ name: 'flip', enabled: false }],
      },
      plugins: [sticky],
      sticky: 'popper',
      maxWidth: '100%',
      appendTo: () => appendTo?.current || 'parent',
      placement: 'top-start',
    },
  };

  return (
    <BubbleMenu
      {...bubbleMenuProps}
      className={FLOATING_BUBBLE_MENU_CLASS}
    >
      <TooltipProvider>
        <TextBubbleContent showListMenu={false} editor={editor} />
      </TooltipProvider>
    </BubbleMenu>
  );
}

