export function useImageUploadOptions(editor: Editor): ImageUploadOptions {
  return useMemo(() => {
    const node = editor.extensionManager.extensions.find(
      (extension) => extension.name === 'imageUpload'
    );

    return node?.options || {};
  }, [editor]);
}

