import { type BlockGroupItem, type BlockItem } from '../../../blocks';
import { Editor } from '@tiptap/core';

type SlashCommandFilterOptions = {
  readonly groups: BlockGroupItem[];
  query: string;
  editor: Editor;
};

export function filterSlashCommands(options: SlashCommandFilterOptions) {
  const { groups, query, editor } = options;
  const newGroups = [...groups];
  let searchQuery = query?.toLowerCase();

  const subCommandMatch = searchQuery.match(/^([^.]+)\./);

  // so if we are inside a subcommand we need to
  // filter the commands based on the remaining search
  if (subCommandMatch) {
    const [match, subCommandId] = subCommandMatch;
    const subCommandGroup = findSubCommandGroup(groups, subCommandId);

    if (subCommandGroup) {
      // headers.something -> headers. -> something (remainingSearch)
      const remainingSearch = searchQuery.slice(match.length);
      const filteredCommands = subCommandGroup.commands.filter(
        (item) => !remainingSearch || isCommandMatch(item, remainingSearch)
      );

      return filteredCommands.length
        ? [
            {
              ...subCommandGroup,
              commands: filteredCommands,
            },
          ]
        : [];
    }
  }

  const filteredGroups = newGroups
    .map((group) => {
      return {
        ...group,
        commands: group.commands.flatMap((item) =>
          processCommand({ item, search: searchQuery, editor })
        ),
      };
    })
    .filter((group) => group.commands.length > 0);

  return filteredGroups;
}

type SubCommandGroup = BlockItem & {
  id: string;
  commands: BlockItem[];
};

function findSubCommandGroup(
  groups: BlockGroupItem[],
  subCommandId: string
): SubCommandGroup | undefined {
  return groups
    .flatMap((group) => group.commands)
    .find(
      (item) =>
        'commands' in item &&
        item.id?.toLowerCase() === subCommandId.toLowerCase()
    ) as SubCommandGroup | undefined;
}

function containsText(text: string | undefined, search: string): boolean {
  if (!text) {
    return false;
  }

  return text.toLowerCase().includes(search.toLowerCase());
}

function isCommandMatch(item: BlockItem, search: string): boolean {
  return (
    containsText(item.title, search) ||
    containsText(item.description, search) ||
    (item.searchTerms?.some((term) => containsText(term, search)) ?? false)
  );
}

function isSubCommand(item: BlockItem): item is SubCommandGroup {
  return 'commands' in item && Array.isArray(item.commands) && !!item.id;
}

type ProcessCommandOptions = {
  item: BlockItem;
  search: string;
  editor: Editor;
};

function processCommand(options: ProcessCommandOptions): BlockItem[] {
  const { item, search, editor } = options;

  const show = item?.render?.(editor);
  if (show === null) {
    return [];
  }

  const isSearching = search.length > 0;
  if (isSubCommand(item)) {
    // if we are not searching, we want to return a navigable command
    // that will navigate to the group so that we can navigate into it
    // using the arrow keys / enter key
    // @ts-expect-error
    const navigableCommand: BlockItem = {
      ...item,
      command: (options) => {
        const { editor, range } = options;
        editor.chain().focus().insertContentAt(range, `/${item.id}.`).run();
      },
    };

    // first check if the item matches the search
    const matched = isCommandMatch(navigableCommand, search);
    if (matched) {
      return [navigableCommand];
    }

    // so the main command does not match the search
    // we need to check if any of the commands match the search
    // if they do, we return the commands instead of the main command
    const hasMatchingCommands =
      navigableCommand?.commands?.some((command) =>
        isCommandMatch(command, search)
      ) ?? false;

    if (!hasMatchingCommands) {
      return [];
    }

    return navigableCommand?.commands ?? [];
  }

  return !isSearching || isCommandMatch(item, search) ? [item] : [];
}

import type { Editor } from '@tiptap/core';
import { type BlockItem } from '../../../blocks';
import { type CSSProperties } from 'react';
import { cn } from '@/lib/utils';
import { SlashCommandItem } from './slash-command-item';

type SlashCommandSubmenuProps = {
  commands: BlockItem[];
  activeIndex: number;
  isFocused: boolean;
  editor: Editor;
  side: 'left' | 'right' | 'overlay';
  style?: CSSProperties;
  onSelect: (index: number) => void;
  onHover: (index: number) => void;
};

// Side-opening submenu, mirroring shadcn's DropdownMenuSubContent. Rendered as a
// sibling of the popup box (not inside its scroll/overflow-hidden container, which
// would clip it). Its measured placement uses whichever side has room, falling
// back to an in-place overlay on narrow viewports.
export function SlashCommandSubmenu(props: SlashCommandSubmenuProps) {
  const {
    commands,
    activeIndex,
    isFocused,
    editor,
    side,
    style,
    onSelect,
    onHover,
  } = props;

  return (
    <div
      data-slot="slash-command-submenu"
      className={cn(
        'bg-popover text-popover-foreground ring-foreground/10 absolute z-50 space-y-0.5 rounded-lg p-1 shadow-lg ring-1 transition-[opacity,transform] duration-100',
        side === 'right' && 'left-full ml-1',
        side === 'left' && 'right-full mr-1',
        side === 'overlay' && 'left-0'
      )}
      style={style}
    >
      {commands.map((item, index) => (
        <SlashCommandItem
          key={index}
          item={item}
          editor={editor}
          isActive={isFocused && index === activeIndex}
          onSelect={() => onSelect(index)}
          onMouseEnter={() => onHover(index)}
        />
      ))}
    </div>
  );
}

import { type BlockGroupItem, type BlockItem } from '../../../blocks/types';
import { Editor, type Range } from '@tiptap/core';
import { ReactRenderer } from '@tiptap/react';
import { type SuggestionOptions } from '@tiptap/suggestion';
import {
  forwardRef,
  Fragment,
  type KeyboardEvent,
  useCallback,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from 'react';
import tippy, { type GetReferenceClientRect, type Instance } from 'tippy.js';
import { getDefaultBlocks } from './default-slash-commands';
import { englishTranslator, type TranslateFn } from '../../i18n';
import { SlashCommandItem } from './slash-command-item';
import { SlashCommandSubmenu } from './slash-command-submenu';
import { filterSlashCommands } from './slash-command-search';
import { Kbd } from '@/components/ui/kbd';

const isSubCommandItem = (item: BlockItem | undefined): boolean =>
  !!item && 'commands' in item;

type SubmenuState = { groupIndex: number; commandIndex: number };
type SubmenuLayout = {
  top: number;
  width: number;
  side: 'left' | 'right' | 'overlay';
};

type CommandListProps = {
  items: BlockGroupItem[];
  command: (item: BlockItem) => void;
  editor: Editor;
  range: Range;
  query: string;
  navigateLabel?: string;
  selectLabel?: string;
  enterLabel?: string;
};

const CommandList = forwardRef<unknown, CommandListProps>((props, ref) => {
  const {
    items: groups,
    command,
    editor,
    range,
    query,
    navigateLabel = englishTranslator('slashCommand.navigate'),
    selectLabel = englishTranslator('slashCommand.select'),
    enterLabel = englishTranslator('slashCommand.enter'),
  } = props;

  const [selectedGroupIndex, setSelectedGroupIndex] = useState(0);
  const [selectedCommandIndex, setSelectedCommandIndex] = useState(0);
  const [submenu, setSubmenu] = useState<SubmenuState | null>(null);
  const [submenuIndex, setSubmenuIndex] = useState(0);
  const [focusInSubmenu, setFocusInSubmenu] = useState(false);
  const [submenuLayout, setSubmenuLayout] = useState<SubmenuLayout>({
    top: 0,
    width: 320,
    side: 'right',
  });

  const prevQuery = useRef('');
  const prevSelectedGroupIndex = useRef(0);
  const prevSelectedCommandIndex = useRef(0);
  // Scroll the active item into view only for keyboard navigation; hovering must
  // not move the scroll position (mouse-over sets the selection too).
  const keyboardNav = useRef(false);

  const openSubItem = submenu
    ? groups[submenu.groupIndex]?.commands[submenu.commandIndex]
    : undefined;
  const submenuCommands: BlockItem[] =
    openSubItem &&
    'commands' in openSubItem &&
    Array.isArray(openSubItem.commands)
      ? openSubItem.commands
      : [];

  const openSubmenu = useCallback(
    (groupIndex: number, commandIndex: number, focus: boolean) => {
      setSelectedGroupIndex(groupIndex);
      setSelectedCommandIndex(commandIndex);
      setSubmenu({ groupIndex, commandIndex });
      setSubmenuIndex(0);
      setFocusInSubmenu(focus);
    },
    []
  );

  const closeSubmenu = useCallback(() => {
    setSubmenu(null);
    setSubmenuIndex(0);
    setFocusInSubmenu(false);
  }, []);

  // Selecting a subcommand opens its flyout; selecting a leaf runs its command.
  const selectItem = useCallback(
    (groupIndex: number, commandIndex: number) => {
      const item = groups[groupIndex]?.commands[commandIndex];
      if (!item) {
        return;
      }

      if (isSubCommandItem(item)) {
        openSubmenu(groupIndex, commandIndex, true);
        return;
      }

      command(item);
    },
    [command, groups, openSubmenu]
  );

  const selectSubItem = useCallback(
    (index: number) => {
      const item = submenuCommands[index];
      if (!item) {
        return;
      }

      command(item);
    },
    [command, submenuCommands]
  );

  const handleItemHover = useCallback(
    (groupIndex: number, commandIndex: number) => {
      keyboardNav.current = false;
      setSelectedGroupIndex(groupIndex);
      setSelectedCommandIndex(commandIndex);

      const item = groups[groupIndex]?.commands[commandIndex];
      if (item && isSubCommandItem(item)) {
        setSubmenu({ groupIndex, commandIndex });
        setSubmenuIndex(0);
        setFocusInSubmenu(false);
      } else {
        closeSubmenu();
      }
    },
    [groups, closeSubmenu]
  );

  const handleSubHover = useCallback((index: number) => {
    setSubmenuIndex(index);
    setFocusInSubmenu(true);
  }, []);

  useImperativeHandle(ref, () => ({
    onKeyDown: ({ event }: { event: KeyboardEvent }) => {
      const navigationKeys = [
        'ArrowUp',
        'ArrowDown',
        'Enter',
        'ArrowLeft',
        'ArrowRight',
      ];
      if (!navigationKeys.includes(event.key)) {
        return false;
      }

      // Keyboard focus is inside the open submenu flyout.
      if (submenu && focusInSubmenu) {
        const count = submenuCommands.length;
        switch (event.key) {
          case 'ArrowDown':
            event.preventDefault();
            if (count) {
              setSubmenuIndex((index) => (index + 1) % count);
            }
            return true;
          case 'ArrowUp':
            event.preventDefault();
            if (count) {
              setSubmenuIndex((index) => (index - 1 + count) % count);
            }
            return true;
          case 'ArrowLeft':
            event.preventDefault();
            closeSubmenu();
            return true;
          case 'ArrowRight':
            event.preventDefault();
            return true;
          case 'Enter':
            if (!count) {
              return false;
            }
            selectSubItem(submenuIndex);
            return true;
          default:
            return false;
        }
      }

      let newCommandIndex = selectedCommandIndex;
      let newGroupIndex = selectedGroupIndex;

      switch (event.key) {
        case 'ArrowLeft': {
          event.preventDefault();

          // Manual `/headers.` query view: step back out to the parent list.
          const group = groups?.[selectedGroupIndex];
          const isInsideSubCommand = group && 'id' in group;
          if (!isInsideSubCommand) {
            return false;
          }

          editor
            .chain()
            .focus()
            .insertContentAt(range, `/${prevQuery.current}`)
            .run();
          setTimeout(() => {
            setSelectedGroupIndex(prevSelectedGroupIndex.current);
            setSelectedCommandIndex(prevSelectedCommandIndex.current);
          }, 0);
          return true;
        }
        case 'ArrowRight': {
          event.preventDefault();

          const item =
            groups?.[selectedGroupIndex]?.commands?.[selectedCommandIndex];
          if (!isSubCommandItem(item)) {
            return false;
          }

          openSubmenu(selectedGroupIndex, selectedCommandIndex, true);
          return true;
        }
        case 'Enter':
          if (!groups.length) {
            return false;
          }
          selectItem(selectedGroupIndex, selectedCommandIndex);

          prevQuery.current = query;
          prevSelectedGroupIndex.current = selectedGroupIndex;
          prevSelectedCommandIndex.current = selectedCommandIndex;
          return true;
        case 'ArrowUp':
          if (!groups.length) {
            return false;
          }
          closeSubmenu();
          keyboardNav.current = true;
          newCommandIndex = selectedCommandIndex - 1;
          newGroupIndex = selectedGroupIndex;
          if (newCommandIndex < 0) {
            newGroupIndex = selectedGroupIndex - 1;
            newCommandIndex = groups[newGroupIndex]?.commands.length - 1 || 0;
          }
          if (newGroupIndex < 0) {
            newGroupIndex = groups.length - 1;
            newCommandIndex = groups[newGroupIndex]?.commands.length - 1 || 0;
          }
          setSelectedGroupIndex(newGroupIndex);
          setSelectedCommandIndex(newCommandIndex);
          return true;
        case 'ArrowDown':
          if (!groups.length) {
            return false;
          }
          closeSubmenu();
          keyboardNav.current = true;
          const commands = groups[selectedGroupIndex].commands;
          newCommandIndex = selectedCommandIndex + 1;
          newGroupIndex = selectedGroupIndex;
          if (commands.length - 1 < newCommandIndex) {
            newCommandIndex = 0;
            newGroupIndex = selectedGroupIndex + 1;
          }
          if (groups.length - 1 < newGroupIndex) {
            newGroupIndex = 0;
          }
          setSelectedGroupIndex(newGroupIndex);
          setSelectedCommandIndex(newCommandIndex);
          return true;
        default:
          return false;
      }
    },
  }));

  const wrapperRef = useRef<HTMLDivElement>(null);
  const commandListContainer = useRef<HTMLDivElement>(null);
  const activeCommandRef = useRef<HTMLButtonElement | null>(null);

  useLayoutEffect(() => {
    // Only auto-scroll on keyboard navigation — hovering also moves the
    // selection, and scrolling on mouse-over makes the list unusable.
    if (!keyboardNav.current) {
      return;
    }
    keyboardNav.current = false;

    const container = commandListContainer?.current;
    const activeCommandContainer = activeCommandRef?.current;
    if (!container || !activeCommandContainer) {
      return;
    }

    const { offsetTop, offsetHeight } = activeCommandContainer;
    container.style.transition = 'none';
    container.scrollTop = offsetTop - offsetHeight;
  }, [
    selectedGroupIndex,
    selectedCommandIndex,
    commandListContainer,
    activeCommandRef,
  ]);

  const updateSubmenuLayout = useCallback(() => {
    if (!submenu) {
      return;
    }

    const trigger = activeCommandRef.current;
    const wrapper = wrapperRef.current;
    if (!trigger || !wrapper) {
      return;
    }

    const triggerRect = trigger.getBoundingClientRect();
    const wrapperRect = wrapper.getBoundingClientRect();
    const viewportGutter = 8;
    const flyoutGap = 4;
    const desiredWidth = 320;
    const minimumUsefulWidth = 192;
    const availableRight = Math.max(
      0,
      window.innerWidth - wrapperRect.right - flyoutGap - viewportGutter
    );
    const availableLeft = Math.max(
      0,
      wrapperRect.left - flyoutGap - viewportGutter
    );

    let side: SubmenuLayout['side'];
    let width: number;

    if (Math.max(availableRight, availableLeft) < minimumUsefulWidth) {
      side = 'overlay';
      width = Math.min(
        desiredWidth,
        window.innerWidth - wrapperRect.left - viewportGutter
      );
    } else {
      side =
        availableRight >= desiredWidth || availableRight >= availableLeft
          ? 'right'
          : 'left';
      width = Math.min(
        desiredWidth,
        side === 'right' ? availableRight : availableLeft
      );
    }

    setSubmenuLayout({
      top: triggerRect.top - wrapperRect.top,
      width,
      side,
    });
  }, [submenu]);

  // Align the submenu flyout to its trigger row and keep it within the viewport.
  useLayoutEffect(() => {
    updateSubmenuLayout();
  }, [updateSubmenuLayout, selectedGroupIndex, selectedCommandIndex]);

  useEffect(() => {
    if (!submenu) {
      return;
    }

    window.addEventListener('resize', updateSubmenuLayout);
    return () => window.removeEventListener('resize', updateSubmenuLayout);
  }, [submenu, updateSubmenuLayout]);

  useEffect(() => {
    setSelectedGroupIndex(0);
    setSelectedCommandIndex(0);
    setSubmenu(null);
    setSubmenuIndex(0);
    setFocusInSubmenu(false);
  }, [groups]);

  useEffect(() => {
    return () => {
      prevQuery.current = '';
      prevSelectedGroupIndex.current = 0;
      prevSelectedCommandIndex.current = 0;
    };
  }, []);

  if (!groups || groups.length === 0) {
    return null;
  }

  return (
    <div ref={wrapperRef} className="relative w-[min(18rem,calc(100vw-1rem))]">
      <div className="bg-popover text-popover-foreground ring-foreground/10 z-50 w-full overflow-hidden rounded-lg shadow-md ring-1 transition-[opacity,transform] duration-100">
        <div
          id="slash-command"
          ref={commandListContainer}
          className="h-auto max-h-[330px] overflow-y-auto p-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
        >
          {groups.map((group, groupIndex) => (
            <Fragment key={groupIndex}>
              {groupIndex > 0 && <div className="bg-border -mx-1 my-1 h-px" />}
              <p className="text-muted-foreground px-2 py-1.5 text-xs font-medium">
                {group.title}
              </p>
              <div className="space-y-0.5">
                {group.commands.map((item, commandIndex) => {
                  const isActive =
                    groupIndex === selectedGroupIndex &&
                    commandIndex === selectedCommandIndex;
                  return (
                    <SlashCommandItem
                      key={`${groupIndex}-${commandIndex}`}
                      item={item}
                      isActive={isActive}
                      editor={editor}
                      onSelect={() => selectItem(groupIndex, commandIndex)}
                      onMouseEnter={() =>
                        handleItemHover(groupIndex, commandIndex)
                      }
                      activeRef={isActive ? activeCommandRef : undefined}
                    />
                  );
                })}
              </div>
            </Fragment>
          ))}
        </div>
        <div className="border-border border-t px-3 py-2">
          <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1">
            <div className="text-muted-foreground flex min-w-0 items-center gap-1.5 text-xs">
              <div className="flex items-center gap-1">
                <Kbd>↑</Kbd>
                <Kbd>↓</Kbd>
              </div>
              <span className="min-w-0 select-none">{navigateLabel}</span>
            </div>
            <div className="text-muted-foreground flex min-w-0 items-center gap-1.5 text-xs">
              <Kbd>{enterLabel}</Kbd>
              <span className="min-w-0 select-none">{selectLabel}</span>
            </div>
          </div>
        </div>
      </div>

      {submenu && submenuCommands.length > 0 && (
        <SlashCommandSubmenu
          commands={submenuCommands}
          activeIndex={submenuIndex}
          isFocused={focusInSubmenu}
          editor={editor}
          side={submenuLayout.side}
          style={{ top: submenuLayout.top, width: submenuLayout.width }}
          onSelect={selectSubItem}
          onHover={handleSubHover}
        />
      )}
    </div>
  );
});

export function getSlashCommandSuggestions(
  groups: BlockGroupItem[] = getDefaultBlocks(englishTranslator),
  t: TranslateFn = englishTranslator
): Omit<SuggestionOptions, 'editor'> {
  const navigateLabel = t('slashCommand.navigate');
  const selectLabel = t('slashCommand.select');
  const enterLabel = t('slashCommand.enter');

  const BoundCommandList = forwardRef<unknown, CommandListProps>(
    (props, ref) => (
      <CommandList
        {...props}
        navigateLabel={navigateLabel}
        selectLabel={selectLabel}
        enterLabel={enterLabel}
        ref={ref}
      />
    )
  );

  return {
    items: ({ query, editor }) => {
      return filterSlashCommands({ query, editor, groups });
    },
    allow: ({ editor }) => {
      const isInsideHTMLCodeBlock = editor.isActive('htmlCodeBlock');
      if (isInsideHTMLCodeBlock) {
        return false;
      }

      return true;
    },
    render: () => {
      let component: ReactRenderer<any>;
      let popup: Instance<any>[] | null = null;

      return {
        onStart: (props) => {
          component = new ReactRenderer(BoundCommandList, {
            props,
            editor: props.editor,
          });

          popup = tippy('body', {
            getReferenceClientRect: props.clientRect as GetReferenceClientRect,
            appendTo: () => document.body,
            content: component.element,
            showOnCreate: true,
            interactive: true,
            trigger: 'manual',
            placement: 'top-start',
          });
        },
        onUpdate: (props) => {
          const currentPopup = popup?.[0];
          if (!currentPopup || currentPopup?.state?.isDestroyed) {
            return;
          }

          component?.updateProps(props);
          currentPopup.setProps({
            getReferenceClientRect: props.clientRect,
          });
        },
        onKeyDown: (props) => {
          if (props.event.key === 'Escape') {
            const currentPopup = popup?.[0];
            if (!currentPopup?.state?.isDestroyed) {
              currentPopup?.destroy();
            }

            component?.destroy();
            return true;
          }

          return component?.ref?.onKeyDown(props);
        },
        onExit: () => {
          if (!popup || !popup?.[0] || !component) {
            return;
          }

          const currentPopup = popup?.[0];
          if (!currentPopup.state.isDestroyed) {
            currentPopup.destroy();
          }

          component?.destroy();
        },
      };
    },
  };
}

