export function VariableView(props: NodeViewProps) {
  const { t } = useMailyContext();
  const { node, updateAttributes, editor } = props;
  const {
    id,
    fallback,
    required,
    hideDefaultValue = false,
    label,
  } = node.attrs;

  const variableOptions = useMemo(() => {
    return getNodeOptions<VariableOptions>(editor, 'variable');
  }, [editor]);
  const renderVariable =
    variableOptions?.renderVariable ?? DEFAULT_RENDER_VARIABLE_FUNCTION;
  const variableChoices = useMemo(() => {
    const choices = processVariables(variableOptions?.variables ?? [], {
      query: '',
      from: 'bubble-variable',
      editor,
    });
    const current = id
      ? (choices.find((variable) => variable.name === id) ?? {
          name: id,
          label,
          required,
          hideDefaultValue,
        })
      : null;
    const remainingChoices = current
      ? choices.filter((variable) => variable.name !== current.name)
      : choices;

    return current ? [current, ...remainingChoices] : remainingChoices;
  }, [
    editor,
    hideDefaultValue,
    id,
    label,
    required,
    variableOptions?.variables,
  ]);
  const hasVariableChoices = variableChoices.length > 0;

  return (
    <NodeViewWrapper
      className="react-component inline-block leading-none"
      draggable="false"
    >
      <Popover
        onOpenChange={(open) => {
          editor.storage.variable.popover = open;
        }}
      >
        <PopoverTrigger
          type="button"
          className="focus-visible:ring-ring/50 focus-visible:ring-offset-background inline-flex select-none items-baseline rounded-md bg-transparent p-0 text-inherit outline-none focus-visible:ring-2 focus-visible:ring-offset-1"
        >
          {renderVariable({
            variable: {
              name: id,
              required: required,
              valid: true,
              label,
            },
            fallback,
            editor,
            from: 'content-variable',
          })}
        </PopoverTrigger>
        <PopoverContent
          align="start"
          side="bottom"
          className={cn(
            'max-w-[calc(100vw-2rem)] rounded-xl p-3 shadow-lg',
            hasVariableChoices ? 'w-[28rem]' : 'w-80'
          )}
          sideOffset={8}
        >
          <div
            className={cn(
              'text-foreground grid gap-3',
              !hideDefaultValue &&
                hasVariableChoices &&
                'sm:grid-cols-[minmax(0,1fr)_minmax(0,0.85fr)]',
              !hideDefaultValue &&
                !hasVariableChoices &&
                'sm:grid-cols-[minmax(0,1fr)_minmax(0,0.85fr)]'
            )}
          >
            <div className="grid gap-1.5">
              <span className="text-muted-foreground text-xs font-medium">
                {t('variableMenu.variable')}
              </span>
              {hasVariableChoices ? (
                <Select
                  label={t('variableMenu.variable')}
                  value={id ?? ''}
                  options={variableChoices.map((variable) => ({
                    value: variable.name,
                    label: variable.label || variable.name,
                  }))}
                  placeholder={t('variableMenu.variablePlaceholder')}
                  className="border-border/70 hover:bg-muted/50 h-9 w-full max-w-none justify-between rounded-lg border bg-transparent px-2.5 text-sm"
                  onValueChange={(value) => {
                    const variable = variableChoices.find(
                      (variable) => variable.name === value
                    );
                    if (variable) {
                      updateAttributes({
                        id: variable.name,
                        label: variable.label,
                        required: variable.required ?? true,
                        hideDefaultValue: variable.hideDefaultValue ?? false,
                      });
                    }
                  }}
                />
              ) : (
                <Input
                  {...AUTOCOMPLETE_PASSWORD_MANAGERS_OFF}
                  value={id ?? ''}
                  onChange={(e) => {
                    updateAttributes({
                      id: e.target.value,
                    });
                  }}
                  placeholder={t('variableMenu.variablePlaceholder')}
                  className="selection:bg-muted-foreground/25 selection:text-foreground focus-visible:ring-ring/35 h-9 font-mono text-sm focus-visible:ring-2"
                />
              )}
            </div>

            {!hideDefaultValue && (
              <label className="grid gap-1.5">
                <span className="text-muted-foreground text-xs font-medium">
                  {t('variableMenu.default')}
                </span>
                <Input
                  {...AUTOCOMPLETE_PASSWORD_MANAGERS_OFF}
                  value={fallback ?? ''}
