    EditorProps,
    'contentHtml' | 'contentJson' | 'onCreate' | 'onUpdate'
  >;
  onError?: (error: unknown, action: string) => void;
  onSent?: (result: unknown) => void;
  onDraftSaved?: (messageId: string) => void;
